import { useMutation } from '@tanstack/react-query'
import gojekApi from '../../axios/gojekPassenger'
import { GENERAL_API_ERROR_MESSAGE } from '../../../helpers/showApiError'
import { formatGojekPhoneValue } from '../../../helpers/formatGojekPhone'

export const GOJEK_ORDER_CHECK_KEY = 'gojek-order-check'
export const GOJEK_BENEFITS_KEY = 'gojek-benefits'
export const GOJEK_VALIDATE_KEY = 'gojek-validate'
export const GOJEK_CREATE_CLAIM_KEY = 'gojek-create-claim'

const pickResponseError = (data) => {
  if (!data || typeof data !== 'object') {
    return ''
  }
  if (typeof data.error === 'string' && data.error.trim()) {
    return data.error
  }
  if (typeof data.message === 'string' && data.message.trim()) {
    return data.message
  }
  return ''
}

export const getGojekApiErrorMessage = (res) => {
  const specific = pickResponseError(res?.data)
  if (specific) {
    return specific
  }
  return GENERAL_API_ERROR_MESSAGE
}

const assertOk = (res) => {
  if (!res || res.status !== 200) {
    const err = new Error(getGojekApiErrorMessage(res))
    err.code = res?.data?.code
    err.status = res?.status
    throw err
  }
  return res.data
}

const withNormalizedPhone = (payload) => {
  if (!payload?.phone_number) {
    return payload
  }
  return { ...payload, phone_number: formatGojekPhoneValue(payload.phone_number) }
}

export { withNormalizedPhone }

export const useGojekOrderCheck = () =>
  useMutation({
    mutationKey: [GOJEK_ORDER_CHECK_KEY],
    mutationFn: async (payload) => {
      const { skip_benefits, requestId, ...apiPayload } = payload
      const res = await gojekApi.postOrderCheck({ payload: withNormalizedPhone(apiPayload) })
      const data = assertOk(res)
      return { ...data, requestId }
    }
  })

export const useGojekBenefits = () =>
  useMutation({
    mutationKey: [GOJEK_BENEFITS_KEY],
    mutationFn: async ({ phone_number, order_id }) => {
      const res = await gojekApi.postBenefitsGojekPassenger({
        payload: withNormalizedPhone({ phone_number, order_id })
      })
      return assertOk(res)
    }
  })

export const useGojekValidateClaim = () =>
  useMutation({
    mutationKey: [GOJEK_VALIDATE_KEY],
    mutationFn: async (payload) => {
      const res = await gojekApi.postValidateClaimGocar({ payload })
      return assertOk(res)
    }
  })

export const useGojekCreateClaim = () =>
  useMutation({
    mutationKey: [GOJEK_CREATE_CLAIM_KEY],
    mutationFn: async (payload) => {
      const res = await gojekApi.createClaimGocarPassenger({ payload })
      return assertOk(res)
    }
  })
