import { useCallback, useEffect, useRef } from 'react'

const DEBOUNCE_MS = 600

const useOrderCheckDebounce = ({ getPhoneNumber, getOrderId, product, onCheck, onClear }) => {
  const requestIdRef = useRef(0)
  const timeoutRef = useRef(null)

  const scheduleOrderCheck = useCallback(() => {
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current)
    }

    timeoutRef.current = setTimeout(() => {
      const phoneNumber = getPhoneNumber()
      const orderId = getOrderId()
      if (phoneNumber && orderId) {
        requestIdRef.current += 1
        const nextId = requestIdRef.current
        onCheck({ phone_number: phoneNumber, order_id: orderId, product, requestId: nextId })
      } else {
        onClear()
      }
    }, DEBOUNCE_MS)
  }, [getPhoneNumber, getOrderId, product, onCheck, onClear])

  useEffect(() => {
    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current)
      }
    }
  }, [])

  return { requestIdRef, scheduleOrderCheck }
}

export default useOrderCheckDebounce
