import React, { useCallback, useState } from 'react'
import { Modal, Spin, Radio, Collapse, Button, Icon, Card } from 'antd'
import { injectIntl } from 'react-intl'
import { isAndroid } from 'react-device-detect'
import ModalClaimConfirmation from '../../../components/ModalClaimConfirmation'
import IntlMessages from '../../../components/utility/intlMessages'
import AlertLimit from '../../../components/Alert'
import ErrorAlert from '../../../components/ErrorAlert'
import ModalStyle from '../modal.style'
import { showApiError, getApiErrorMessage } from '../../../helpers/showApiError'
import {
  useGojekValidateClaim,
  useGojekCreateClaim
} from '../../../request/query/gojek'

const REACT_APP_ANDROID = process.env.REACT_APP_ANDROID
const RadioGroup = Radio.Group
const Panel = Collapse.Panel

const BenefitsModal = ({
  intl,
  isOpen,
  benefits,
  profile,
  product,
  history,
  isClose
}) => {
  const [value, setValue] = useState('')
  const [displaySafeScreen, setDisplaySafeScreen] = useState(false)
  const [showValidatePopup, setShowValidatePopup] = useState(false)
  const [validatePopupMessage, setValidatePopupMessage] = useState('')
  const [displayLimitAlert, setDisplayLimitAlert] = useState(false)
  const [displayErrorMessage, setDisplayErrorMessage] = useState('')
  const [dataValidate, setDataValidate] = useState({})

  const validateMutation = useGojekValidateClaim()
  const createMutation = useGojekCreateClaim()

  const intlText = useCallback((messageObj = { id: ' ' }) => {
    return intl.formatMessage(messageObj)
  }, [intl])

  const notifyError = useCallback((err) => {
    showApiError(err, intl)
  }, [intl])

  const getSource = () => {
    const source = window.sessionStorage.getItem('utm_source')
    return source || 'direct'
  }

  const handleClaimSuccess = useCallback((dataClaim) => {
    const isGojek = window.sessionStorage.getItem('isFromGojek')
    const isGoDriver = window.sessionStorage.getItem('isFromGoDriver')

    const onPopState = () => {
      history.push(`/${product}/claim-form`)
    }
    window.onpopstate = onPopState

    if (REACT_APP_ANDROID && isAndroid && (isGojek || isGoDriver)) {
      history.push(`/${product}/${dataClaim.claim_no}/success`)
    } else {
      history.push(`/${product}/claim-details/${dataClaim.claim_id}`)
    }
  }, [history, product])

  const createClaim = useCallback(() => {
    const payload = {
      order_id: profile.orderId,
      user_id: profile.user_id,
      benefit_id: value,
      source: getSource(),
      product
    }

    createMutation.mutate(payload, {
      onSuccess: (data) => {
        handleClaimSuccess(data)
      },
      onError: (err) => {
        setDisplayErrorMessage(getApiErrorMessage(err))
        notifyError(err)
      }
    })
  }, [profile, value, product, createMutation, handleClaimSuccess, notifyError])

  const handleValidateSuccess = useCallback((data) => {
    const {
      claim_id: claimId,
      is_claimable: isClaimable,
      is_first_claim: isFirstClaim,
      error_message: errorMessage
    } = data

    if (claimId === null && isFirstClaim === true) {
      createClaim()
    } else if (claimId !== null && (isFirstClaim === true || isFirstClaim === false)) {
      history.push(`/claimdetail/${claimId}`)
    } else if (claimId === null && isFirstClaim === false && isClaimable === false) {
      setDisplaySafeScreen(true)
    } else {
      setShowValidatePopup(true)
      setValidatePopupMessage(errorMessage)
      setDataValidate(data)
    }
  }, [createClaim, history])

  const validate = useCallback(() => {
    setDisplayErrorMessage('')
    const payload = {
      order_id: profile.orderId,
      user_id: profile.user_id,
      benefit_id: value,
      product
    }

    validateMutation.mutate(payload, {
      onSuccess: handleValidateSuccess,
      onError: (err) => {
        if (err.code === 'CLAIM_109') {
          setDisplayLimitAlert(true)
        } else {
          setDisplayErrorMessage(getApiErrorMessage(err))
          notifyError(err)
        }
      }
    })
  }, [profile, value, product, validateMutation, handleValidateSuccess, notifyError])

  const handleCancelShowBenefits = useCallback(() => {
    window.onpopstate = null
    setValue('')
    isClose()
  }, [isClose])

  const handleChange = useCallback((e) => {
    setValue(e.target.value)
    setDisplayLimitAlert(false)
  }, [])

  const genExtra = useCallback(() => (
    <Icon type='down' />
  ), [])

  const handleOkClaimValidation = useCallback(() => {
    createClaim()
  }, [createClaim])

  const handleCancelClaimValidation = useCallback(() => {
    setShowValidatePopup(false)
  }, [])

  const backToBenefit = useCallback(() => {
    setDisplaySafeScreen(false)
  }, [])

  const onCloseDisplayError = useCallback(() => {
    setDisplayErrorMessage('')
  }, [])

  const noBenefitInfo = () => (
    <div>
      <Card>
        <h3><IntlMessages id='Anda dalam perlindungan yang tepat' /></h3>
        <p>
          <IntlMessages id='Untuk info lebih lengkap hubungi customer service kami pada nomor di bawah ini' />
          {' '}&amp; <IntlMessages id='daftarkan klaim anda' />
        </p>
        <p>
          <IntlMessages id='Chat dengan customer service kami melalu nomor whatsapp dibawah ini' />
          {' '}&amp; <IntlMessages id='daftarkan klaim anda' />
        </p>
        <span style={{ fontSize: '24px' }}>
          <i className='fab fa-whatsapp' /> &nbsp;&nbsp; (+62) 818 343 494
        </span>
      </Card>
      <div className='next-btn-container'>
        <Button type='primary' onClick={backToBenefit}>
          <IntlMessages id='Back' />
        </Button>
      </div>
    </div>
  )

  const btnLoading = validateMutation.isLoading || createMutation.isLoading

  return (
    <div>
      <ModalClaimConfirmation
        isOpen={showValidatePopup}
        message={validatePopupMessage}
        dataValidate={dataValidate}
        onOk={handleOkClaimValidation}
        onCancel={handleCancelClaimValidation}
        confirmDelayMs={2000}
        confirmLoading={createMutation.isLoading}
      />
      <Modal
        title={
          <ModalStyle>
            <div className='modal-text'>
              {intlText({ id: 'Pilih manfaat untuk klaim' })}
            </div>
          </ModalStyle>
        }
        visible={isOpen}
        footer={null}
        onCancel={handleCancelShowBenefits}
        wrapClassName='benefits-modal'
        maskClosable={false}
      >
        {displayLimitAlert && <AlertLimit />}
        {displayErrorMessage !== '' && (
          <ErrorAlert
            message={intlText({ id: displayErrorMessage })}
            type='error'
            onClose={onCloseDisplayError}
          />
        )}
        <Spin spinning={benefits === undefined} tip='Loading...'>
          {displaySafeScreen ? noBenefitInfo() : (
            (benefits !== undefined && benefits.length > 0) && (
              <RadioGroup
                onChange={handleChange}
                value={value}
                className='benefits-radio'
              >
                {benefits.map((val, index) => {
                  if (val.benefits.length > 1) {
                    return (
                      <Collapse key={index}>
                        <Panel
                          header={
                            <div className='benefits-collapse-header'>
                              <b><IntlMessages id={val.benefit_group_name} /></b>
                              <br />
                              <span><IntlMessages id={val.benefit_group_description} /></span>
                            </div>
                          }
                          key={index}
                          extra={genExtra()}
                        >
                          {val.benefits.map((benefitItem, i) => (
                            <Radio
                              key={i}
                              value={benefitItem.benefit_id}
                            >
                              <b><IntlMessages id={benefitItem.benefit_name} /></b>
                            </Radio>
                          ))}
                        </Panel>
                      </Collapse>
                    )
                  }
                  return val.benefits.map((benefitItem, i) => (
                    <div key={i} className='radio-content-wrapper'>
                      <Radio
                        value={benefitItem.benefit_id}
                      >
                        <b><IntlMessages id={benefitItem.benefit_name} /></b>
                        <br />
                        <span className='description'>
                          <IntlMessages id={benefitItem.description} />
                        </span>
                      </Radio>
                      <br />
                    </div>
                  ))
                })}
                <div className='next-btn-container'>
                  <Button
                    type='primary'
                    disabled={value === ''}
                    onClick={validate}
                    loading={btnLoading}
                  >
                    <IntlMessages id='Next' />
                  </Button>
                </div>
              </RadioGroup>
            )
          )}
          {(benefits !== undefined && benefits.length < 1) && (
            <h3><IntlMessages id='Benefits not found' /></h3>
          )}
        </Spin>
      </Modal>
    </div>
  )
}

export default injectIntl(BenefitsModal)
