import React from 'react'
import { Modal, Button } from 'antd'
import { injectIntl } from 'react-intl'
import IntlMessages from '../utility/intlMessages'

class ModalClaimConfirmation extends React.Component {
  state = {
    loading: false
  }

  componentDidUpdate (prevProps) {
    if (prevProps.isOpen && !this.props.isOpen) {
      this.setState({ loading: false })
    }
  }

  handleCancel = () => {
    this.setState({ loading: false })
    this.props.onCancel()
  }

  handleOk = () => {
    this.setState({ loading: true })
    const { onOk, confirmDelayMs = 0 } = this.props
    if (confirmDelayMs > 0) {
      setTimeout(onOk, confirmDelayMs)
    } else {
      onOk()
    }
  }

  intlText = (messageObj = { id: ' ' }) => {
    return this.props.intl.formatMessage(messageObj)
  }

  render () {
    const { isOpen, message, dataValidate, confirmLoading } = this.props
    const loading = confirmLoading !== undefined ? confirmLoading : this.state.loading

    return (
      <Modal
        title={this.intlText({ id: 'Initiate new claim' })}
        visible={isOpen}
        footer={null}
        closable={false}
        wrapClassName='benefits-modal'
        maskClosable={false}
        centered
      >
        <div className='claim-validation-content'>
          <IntlMessages id={message} values={dataValidate} />
        </div>
        <div className='claim-validation-footer'>
          <Button
            className='yes-btn-claim-validation'
            onClick={this.handleOk}
            loading={loading}
          ><IntlMessages id='YES' /></Button>
          <Button
            className='no-btn-claim-validation'
            onClick={this.handleCancel}
          ><IntlMessages id='NO' /></Button>
        </div>
      </Modal>
    )
  }
}

export default injectIntl(ModalClaimConfirmation)
