import React, { useCallback, useMemo, useState } from 'react'
import { Alert, Button, Card, Col, Form, Input, Row, Divider, Icon } from 'antd'
import { injectIntl } from 'react-intl'
import { connect } from 'react-redux'
import IntlMessages from '../../../components/utility/intlMessages'
import authActions from '../../../redux/auth/actions'
import GojekStyled from '../gojek.style'
import BenefitsModal from './BenefitsModal'
import NumericInput from '../numericinput'
import GoPassengerModal from '../goPassengerModal'
import GoDriverModal from '../goDriverModal'
import formatGojekPhone from '../../../helpers/formatGojekPhone'
import { getApiErrorMessage, showApiError } from '../../../helpers/showApiError'
import useOrderCheckDebounce from './useOrderCheckDebounce'
import {
  useGojekOrderCheck,
  useGojekBenefits,
} from '../../../request/query/gojek'

const FormItem = Form.Item
const { updateUser } = authActions

const ClaimForm = ({ form, dataUser, history, updateUser, intl }) => {
  const [orderResult, setOrderResult] = useState({})
  const [orderId, setOrderId] = useState('')
  const [benefitsModal, setBenefitsModal] = useState(false)
  const [benefits, setBenefits] = useState(undefined)
  const [isOrderSubmitted, setIsOrderSubmitted] = useState(false)
  const [submitError, setSubmitError] = useState('')
  const [visible, setVisible] = useState(false)
  const [manualPhone, setManualPhone] = useState('')

  const product = useMemo(() => {
    if (history?.location?.pathname === '/go-driver/claim-form') {
      return 'go-driver'
    }
    return 'gojek-passenger'
  }, [history])

  const formTitleId =
    product === 'go-driver' ? 'Go Driver Claim' : 'Go Passenger Claim'

  const profilePhoneRaw =
    dataUser?.phone || window.sessionStorage.getItem('verifyPhone') || ''

  const profilePhoneParsed = useMemo(() => {
    return formatGojekPhone(profilePhoneRaw)
  }, [profilePhoneRaw])

  const isPhoneReadonly = profilePhoneParsed.isValid

  const getPhoneNumber = useCallback(() => {
    if (profilePhoneParsed.isValid) {
      return profilePhoneParsed.value
    }
    return formatGojekPhone(manualPhone).value
  }, [profilePhoneParsed, manualPhone])

  const orderCheck = useGojekOrderCheck()
  const benefitsMutation = useGojekBenefits()

  const notifyError = useCallback(
    (err) => {
      showApiError(err, intl)
    },
    [intl]
  )

  const handleClear = useCallback(() => {
    setOrderResult({})
    form.setFieldsValue({ name: '', email: '' })
  }, [form])

  const handleOrderCheck = useCallback(
    (payload) => {
      orderCheck.mutate(
        { ...payload, skip_benefits: true },
        {
          onSuccess: (data) => {
            if (data.requestId !== payload.requestId) {
              return
            }
            setOrderResult(data)
            form.setFieldsValue({
              name: data.name || '',
              email: data.email || '',
            })
          },
          onError: (err) => {
            handleClear()
            notifyError(err)
          },
        }
      )
    },
    [orderCheck, form, handleClear, notifyError]
  )

  const getOrderId = useCallback(() => form.getFieldValue('order_id'), [form])

  const { scheduleOrderCheck } = useOrderCheckDebounce({
    getPhoneNumber,
    getOrderId,
    product,
    onCheck: handleOrderCheck,
    onClear: handleClear,
  })

  const validateForm = useCallback(() => {
    return new Promise((resolve) => {
      form.validateFields((error) => {
        resolve(!error)
      })
    })
  }, [form])

  const handleOrderIdChange = useCallback(
    (value) => {
      setOrderId(value)
      scheduleOrderCheck()
    },
    [scheduleOrderCheck]
  )

  const handleManualPhoneChange = useCallback(
    (e) => {
      setManualPhone(e.target.value)
      scheduleOrderCheck()
    },
    [scheduleOrderCheck]
  )

  const handleShowModal = useCallback(() => {
    setVisible(true)
  }, [])

  const handleCancelModal = useCallback(() => {
    setVisible(false)
  }, [])

  const handleCloseBenefitModal = useCallback(() => {
    setBenefitsModal(false)
  }, [])

  const handleCloseError = useCallback(() => {
    setSubmitError('')
  }, [])

  const openBenefitsModal = useCallback(
    (values) => {
      const phone = getPhoneNumber()
      setIsOrderSubmitted(true)
      updateUser({ name: values.name, email: values.email || '' })

      benefitsMutation.mutate(
        { phone_number: phone, order_id: values.order_id },
        {
          onSuccess: (benefitsData) => {
            setBenefits(benefitsData)
            setBenefitsModal(true)
          },
          onError: (err) => {
            setIsOrderSubmitted(false)
            setSubmitError(getApiErrorMessage(err))
            notifyError(err)
          },
        }
      )
    },
    [orderResult, getPhoneNumber, benefitsMutation, updateUser, notifyError]
  )

  const handleSubmit = useCallback(
    async (e) => {
      e.preventDefault()
      setSubmitError('')

      const valid = await validateForm()
      if (!valid) {
        return
      }

      const values = form.getFieldsValue()
      window.sessionStorage.setItem('email', values.email || '')

      const phone = getPhoneNumber()
      const userId = orderResult.user_id || dataUser?.user_id
      const alreadyChecked = !!(
        orderResult.user_id &&
        orderResult.name &&
        values.order_id === orderId
      )

      if (alreadyChecked) {
        openBenefitsModal(values)
        return
      }

      const payload = {
        ...values,
        phone_number: phone,
        user_id: userId,
        product,
      }

      orderCheck.mutate(payload, {
        onSuccess: (data) => {
          setOrderResult(data)
          openBenefitsModal(values)
        },
        onError: (err) => {
          setIsOrderSubmitted(false)
          setSubmitError(getApiErrorMessage(err))
          notifyError(err)
        },
      })
    },
    [
      validateForm,
      form,
      orderResult,
      getPhoneNumber,
      orderId,
      dataUser,
      product,
      orderCheck,
      openBenefitsModal,
      notifyError,
    ]
  )

  const { getFieldDecorator } = form
  const apiPhoneNumber = getPhoneNumber()
  const canSubmit = !!(orderId && orderResult.name && apiPhoneNumber)
  const isLoading = orderCheck.isLoading || benefitsMutation.isLoading
  const profile = {
    orderId,
    user_id: orderResult.user_id || dataUser?.user_id,
    name: orderResult.name,
    email: orderResult.email,
  }

  const stylePrevent = visible ? { display: 'none' } : {}

  return (
    <div>
      <GojekStyled>
        <Row style={{ display: 'flex', justifyContent: 'center' }}>
          {isOrderSubmitted && orderResult.user_id && (
            <BenefitsModal
              isOpen={benefitsModal}
              benefits={benefits}
              isClose={handleCloseBenefitModal}
              product={product}
              profile={profile}
              history={history}
            />
          )}
          {product === 'go-driver' ? (
            <GoDriverModal visible={visible} handleCancel={handleCancelModal} />
          ) : (
            <GoPassengerModal
              visible={visible}
              handleCancel={handleCancelModal}
            />
          )}
          <Col xs={24} sm={24} md={12} lg={12} xl={12}>
            <h1
              style={{
                fontSize: '18px',
                fontWeight: '700',
                textAlign: 'center',
                marginBottom: '8px',
              }}
            >
              <IntlMessages id={formTitleId} />
            </h1>
            <label className="label">
              <strong>
                <IntlMessages id="Silakan lengkapi form dibawah untuk proses pengajuan klaim" />
              </strong>
            </label>
            <Divider className="divider" />
            <Card className="form-cards">
              {submitError !== '' && (
                <Row>
                  <Col>
                    <Alert
                      style={{ marginBottom: '10px' }}
                      description={submitError}
                      type="error"
                      showIcon
                      closable
                      onClose={handleCloseError}
                    />
                  </Col>
                </Row>
              )}
              <Form onSubmit={handleSubmit} id="gojekClaimForm">
                <Row className="form-container">
                  <Col
                    xs={24}
                    sm={24}
                    md={7}
                    lg={7}
                    style={{ marginTop: '8px' }}
                  >
                    <label style={{ marginTop: '10px' }}>
                      <IntlMessages id="Nomor Order" />
                    </label>
                  </Col>
                  <Col xs={24} sm={24} md={17} lg={17}>
                    <FormItem>
                      {getFieldDecorator('order_id', {
                        rules: [
                          {
                            required: true,
                            message: (
                              <IntlMessages id="Nomor pesanan tidak boleh kosong" />
                            ),
                          },
                        ],
                      })(<NumericInput onChange={handleOrderIdChange} />)}
                    </FormItem>
                  </Col>
                </Row>
                <Row className="form-container">
                  <Col
                    xs={24}
                    sm={24}
                    md={7}
                    lg={7}
                    style={{ marginTop: '8px' }}
                  >
                    <label style={{ marginTop: '10px' }}>
                      <IntlMessages id="Nomor Handphone" />
                    </label>
                  </Col>
                  <Col xs={24} sm={24} md={17} lg={17}>
                    <FormItem>
                      {isPhoneReadonly ? (
                        <Input
                          value={profilePhoneParsed.value}
                          disabled
                          readOnly
                        />
                      ) : (
                        <Input
                          value={manualPhone}
                          onChange={handleManualPhoneChange}
                          placeholder="+628123456789"
                        />
                      )}
                    </FormItem>
                    {!isPhoneReadonly && (
                      <Alert
                        style={{ marginBottom: '10px' }}
                        type="info"
                        showIcon
                        message={
                          <IntlMessages id="Masukkan nomor dalam format +[kode negara][nomor tanpa angka 0 di depan], contoh: +628123456789" />
                        }
                      />
                    )}
                  </Col>
                </Row>
                <Row className="form-container">
                  <Col
                    xs={24}
                    sm={24}
                    md={7}
                    lg={7}
                    style={{ marginTop: '8px' }}
                  >
                    <label style={{ marginTop: '10px' }}>
                      <IntlMessages id={'Nama sesuai KTP'} />
                    </label>
                  </Col>
                  <Col xs={24} sm={24} md={17} lg={17}>
                    <FormItem>
                      {getFieldDecorator('name', {
                        rules: [
                          {
                            required: true,
                            message: (
                              <IntlMessages id="Nama tidak boleh kosong" />
                            ),
                          },
                        ],
                      })(
                        <Input
                          disabled
                          suffix={
                            orderCheck.isLoading ? (
                              <Icon type="loading" />
                            ) : null
                          }
                        />
                      )}
                    </FormItem>
                  </Col>
                </Row>
                <Row className="form-container">
                  <Col
                    xs={24}
                    sm={24}
                    md={7}
                    lg={7}
                    style={{ marginTop: '8px' }}
                  >
                    <label style={{ marginTop: '10px' }}>
                      <IntlMessages id="Email terdaftar" />
                    </label>
                  </Col>
                  <Col xs={24} sm={24} md={17} lg={17}>
                    <FormItem>
                      {getFieldDecorator('email', {
                        initialValue: '',
                        rules: [
                          {
                            type: 'email',
                            message: <IntlMessages id="Email tidak valid" />,
                          },
                        ],
                      })(
                        <Input
                          disabled
                          suffix={
                            orderCheck.isLoading ? (
                              <Icon type="loading" />
                            ) : null
                          }
                        />
                      )}
                    </FormItem>
                  </Col>
                </Row>
                <Row>
                  <Col>
                    <div className="how-to-get-order-id">
                      <p onClick={handleShowModal}>
                        <IntlMessages id="Klik disini untuk cara menemukan Nomor Order" />
                      </p>
                    </div>
                  </Col>
                </Row>
                <Divider className="divider" />
                <Row>
                  <Col>
                    <div className="term">
                      <p>
                        <IntlMessages id="Catatan: Kelengkapan dokumen klaim ditunggu maksimal 30 hari setelah kejadian" />
                      </p>
                    </div>
                  </Col>
                </Row>
                <Row>
                  <Col>
                    <div
                      className="btn-form-order-container"
                      style={{
                        display: 'flex',
                        justifyContent: 'center',
                        flexDirection: 'column',
                        alignItems: 'center',
                      }}
                    >
                      <Button
                        style={stylePrevent}
                        disabled={!canSubmit}
                        type="primary"
                        className="button btn-form-order"
                        htmlType="submit"
                        form="gojekClaimForm"
                        loading={isLoading}
                      >
                        <span className="godriver-text">
                          <IntlMessages id="BUAT KLAIM" />
                        </span>
                      </Button>
                    </div>
                  </Col>
                </Row>
              </Form>
            </Card>
          </Col>
        </Row>
      </GojekStyled>
    </div>
  )
}

const ClaimFormWrapped = Form.create()(ClaimForm)

export default connect(
  (state) => ({
    dataUser: state.User.details,
  }),
  { updateUser }
)(injectIntl(ClaimFormWrapped))
