const E164_REGEX = /^\+\d{7,15}$/
const STRIP_LEADING_ZERO_AFTER_CC = /^\+(\d{1,3})0+(\d{6,})$/

const INVALID_RESULT = { value: '', isValid: false, raw: '' }

/**
 * Normalize phone to E.164 (+{CC}{national}) for Gojek order-check API.
 * ponytail: regex-only multi-region; no libphonenumber — ambiguous CC edge cases possible.
 */
const formatGojekPhone = (phone) => {
  const raw = typeof phone === 'string' ? phone.trim() : ''
  if (!raw) {
    return { ...INVALID_RESULT, raw: '' }
  }

  let normalized = raw.replace(/[^\d+]/g, '')

  if (!normalized.startsWith('+')) {
    if (normalized.startsWith('0')) {
      normalized = `+62${normalized.slice(1)}`
    } else if (normalized.startsWith('62')) {
      normalized = `+${normalized}`
    } else {
      normalized = `+${normalized}`
    }
  }

  const zeroFix = normalized.match(STRIP_LEADING_ZERO_AFTER_CC)
  if (zeroFix) {
    normalized = `+${zeroFix[1]}${zeroFix[2]}`
  }

  if (E164_REGEX.test(normalized)) {
    return { value: normalized, isValid: true, raw }
  }

  return { value: '', isValid: false, raw }
}

export const formatGojekPhoneValue = (phone) => formatGojekPhone(phone).value

export default formatGojekPhone
